const item = $input.first().json;
const webhookBase = 'https://oiukjhjiofgfgnbfg.app.n8n.cloud/webhook/track-open';

const emailId = String(item.id || '').trim();
const recipient = String(item.contact || '').trim();
const campaign = String(item.name || '').trim();
const subject = String(item.subject || 'Quick Idea For Your Store').trim();
const step = item.step;
const rawMessage = item[`message_${step}`] || '';

const chunks = rawMessage.split(/\n\n+/).map(p => p.trim()).filter(p => p.length > 0);

const merged = [];
for (const chunk of chunks) {
  const singleLine = chunk.replace(/\n/g, ' ');
  const startsLower = /^[a-z]/.test(singleLine);
  if (startsLower && merged.length > 0) {
    merged[merged.length - 1] += ' ' + singleLine;
  } else {
    merged.push(singleLine);
  }
}

const paragraphs = merged
  .map(p => {
    if (p.startsWith('- ') || p.includes('\n- ')) {
      const parts = p.split(/- /).filter(i => i.trim());
      const listItems = parts.map(i => `<li style="margin-bottom:6px;">${i.trim()}</li>`).join('\n');
      return `<ul style="margin:0 0 14px 0; padding-left:20px;">${listItems}</ul>`;
    }
    return `<p style="margin:0 0 14px 0;">${p}</p>`;
  })
  .join('\n');

const pixelUrl = `${webhookBase}?eid=${encodeURIComponent(emailId)}&to=${encodeURIComponent(recipient)}&c=${encodeURIComponent(campaign)}`;

const html = `<!DOCTYPE html>\n<html>\n<body style="font-family: Arial, sans-serif; font-size: 15px; color: #333; padding: 20px; line-height: 1.6;">\n${paragraphs}\n<img src="${pixelUrl}" width="1" height="1" style="display:block;" alt="" />\n</body>\n</html>`;

return [{
  json: {
    ...item,
    html_body: html,
    pixel_subject: subject
  }
}];

