const readableDate = $json["Readable date"];
const cleaned = readableDate.replace(/(\d+)(st|nd|rd|th)/, "$1");
const dateObj = new Date(cleaned);
const date = dateObj.toISOString().slice(0, 10);
const hour = dateObj.getHours();
const minutes = dateObj.getMinutes() < 30 ? "00" : "30";
const time = minutes === "00" ? `${hour}` : `${hour}:30`;
return [{ json: { date, time } }];

const webhookData = $('Webhook - Catch Open1').first().json;
const query = webhookData.query;
const headers = webhookData.headers;
const dbRow = $input.first().json;

const sentAt = parseInt(query.st || '0');   // unix ms from pixel URL
const openedAt = $now.toMillis();           // n8n built-in, correct timezone
const diffMinutes = (openedAt - sentAt) / 1000 / 60;

if (sentAt > 0 && diffMinutes < 2) {
  return [];  // scanner fired too fast
}

const emailId = decodeURIComponent(query.eid || 'unknown');
const recipient = decodeURIComponent(query.to || 'unknown');
const campaign = decodeURIComponent(query.c || 'general');
const ip = headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown';
const userAgent = headers['user-agent'] || 'unknown';

return [{
  json: {
    email_id: emailId,
    recipient: recipient,
    campaign: campaign,
    event: 'opened',
    date: $now.toISODate(),
    time: $now.toFormat('HH:mm:ss'),
    timestamp: $now.toISO(),
    ip_address: ip,
    user_agent: userAgent
  }
}];

// ── GUARD 2: Ignore opens that arrive within 2 minutes of send ──────────────
// Gmail's own scanner fires the pixel almost instantly after send.
// Real human opens happen at least a couple of minutes later.
const item = $input.first().json;

const sentAt = new Date(item.created_at || item.date);
const openedAt = new Date(); // now
const diffMs = openedAt.getTime() - sentAt.getTime();
const twoMinutes = 2 * 60 * 1000;

if (diffMs < twoMinutes) {
  // Too fast — almost certainly a scanner. Drop silently.
  return [];
}

return [{ json: item }];
